<script setup>
import { onMounted,ref } from 'vue';import {useRoute} from 'vue-router';import {request} from '../services/api';import {formatMoney as money} from '../utils/money';import {useContentStore} from '../stores/content';
const route=useRoute(),store=useContentStore(),p=ref(null),error=ref('');const name=v=>v?`${v.nombres} ${v.apellidos}`:'No disponible';
const date=d=>new Date(d).toLocaleString('es-GT',{timeZone:'America/Guatemala'});function print(){window.print();}
onMounted(async()=>{try{p.value=await request('/pagos/'+route.params.id);}catch(e){error.value=e.message;}});
</script>
<template><p v-if="error" class="feedback error" role="alert">{{error}}</p><p v-else-if="!p">Cargando comprobante…</p><template v-else><div class="actions no-print"><RouterLink to="/admin/pagos" class="button secondary">Volver a pagos</RouterLink><button class="button" @click="print">Imprimir comprobante</button></div><article class="receipt form-panel"><h1>{{store.content?.nombreCentro||'SIGCA'}}</h1><h2>Comprobante interno de pago</h2><p class="number">{{p.comprobante}}</p><p><strong>{{p.estado}}</strong></p><dl><dt>Paciente</dt><dd>{{name(p.paciente)}}</dd><dt>Cita</dt><dd>{{p.cita?.fecha}} · {{p.cita?.horaInicio}} · {{p.cita?.servicio?.nombre}}</dd><dt>Monto recibido</dt><dd>{{money(p.montoCentavos)}}</dd><dt>Método</dt><dd>{{p.metodo}}</dd><dt>Fecha</dt><dd>{{date(p.registradoEn)}}</dd><dt>Registrado por</dt><dd>{{name(p.registradoPor)}}</dd><template v-if="p.estado==='ANULADO'"><dt>Anulado por</dt><dd>{{name(p.anuladoPor)}} · {{date(p.anuladoEn)}}</dd><dt>Motivo</dt><dd>{{p.motivoAnulacion}}</dd></template></dl><p>Este comprobante corresponde a un pago o abono. No constituye una factura fiscal.</p></article></template></template>
<style scoped>.receipt{max-width:760px;margin:24px auto}.number{overflow-wrap:anywhere}.receipt dl{display:grid;grid-template-columns:minmax(100px,1fr) 2fr;gap:12px}.receipt dd{margin:0;overflow-wrap:anywhere}@media print{.receipt{border:0;box-shadow:none;margin:0;padding:0;position:absolute;left:0;top:0;width:100%;max-width:none}}</style>
<style>@media print{body:has(.receipt) *{visibility:hidden}.receipt,.receipt *{visibility:visible}.no-print{display:none}}</style>
